     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       background:
         radial-gradient(circle at top left, rgba(49, 109, 255, 0.16), transparent 32%),
         radial-gradient(circle at bottom right, rgba(131, 104, 255, 0.14), transparent 30%),
         var(--bg);
       color: var(--text);
       display: grid;
       place-items: center;
       padding: 32px 20px;
     }

     .page {
       width: min(100%, 960px);
     }

     .frame {
       display: grid;
       gap: 28px;
       grid-template-columns: minmax(0, 1.4fr) minmax(280px, 0.8fr);
       align-items: stretch;
       background: var(--surface);
       border: 1px solid rgba(255, 255, 255, 0.65);
       backdrop-filter: blur(18px);
       box-shadow: var(--shadow);
       border-radius: 28px;
       padding: 28px;
     }

     .preview-card {
       background: linear-gradient(180deg, #ffffff, #f7f9fc);
       border: 1px solid var(--border);
       border-radius: 24px;
       padding: 22px;
       display: grid;
       gap: 18px;
     }

     .preview-image {
       width: 100%;
       aspect-ratio: 4 / 3;
       object-fit: cover;
       display: block;
       border-radius: 20px;
       box-shadow: 0 16px 40px rgba(29, 45, 80, 0.16);
     }

     .preview-meta {
       display: flex;
       justify-content: space-between;
       gap: 16px;
       align-items: center;
       flex-wrap: wrap;
     }

     .eyebrow {
       display: inline-flex;
       align-items: center;
       gap: 8px;
       padding: 8px 12px;
       border-radius: 999px;
       background: rgba(49, 109, 255, 0.1);
       color: var(--primary);
       font-size: 0.84rem;
       font-weight: 700;
       letter-spacing: 0.02em;
     }

     h1 {
       margin: 12px 0 8px;
       font-size: clamp(2rem, 5vw, 3.4rem);
       line-height: 1;
       letter-spacing: -0.04em;
     }

     p {
       margin: 0;
       color: var(--muted);
       line-height: 1.6;
     }

     .details {
       display: grid;
       gap: 18px;
       align-content: center;
       padding: 16px 8px;
     }

     .stats {
       display: grid;
       grid-template-columns: repeat(2, minmax(0, 1fr));
       gap: 12px;
       margin-top: 8px;
     }

     .stat {
       background: rgba(255, 255, 255, 0.78);
       border: 1px solid var(--border);
       border-radius: 18px;
       padding: 16px;
     }

     .stat span {
       display: block;
     }

     .stat-label {
       font-size: 0.84rem;
       color: var(--muted);
       margin-bottom: 6px;
     }

     .stat-value {
       font-size: 1.05rem;
       font-weight: 700;
       color: var(--text);
     }

     .actions {
       display: flex;
       gap: 12px;
       flex-wrap: wrap;
       margin-top: 10px;
     }

     button {
       appearance: none;
       border: 0;
       border-radius: 14px;
       padding: 14px 18px;
       font: inherit;
       font-weight: 700;
       cursor: pointer;
       transition: transform 160ms ease, box-shadow 160ms ease, background 160ms ease, opacity 160ms ease;
     }

     button:hover {
       transform: translateY(-1px);
     }

     button:focus-visible {
       outline: 3px solid rgba(49, 109, 255, 0.28);
       outline-offset: 3px;
     }

     .secondary {
       background: #eef3ff;
       color: var(--primary);
     }

     .trigger,
     .danger {
       background: var(--danger);
       color: #fff;
       box-shadow: 0 14px 30px rgba(229, 72, 77, 0.28);
     }

     .trigger:hover,
     .danger:hover {
       background: var(--danger-strong);
     }

     .dialog-backdrop {
       position: fixed;
       inset: 0;
       background: rgba(10, 16, 28, 0.5);
       backdrop-filter: blur(8px);
       display: grid;
       place-items: center;
       padding: 20px;
       opacity: 0;
       visibility: hidden;
       pointer-events: none;
       transition: opacity 180ms ease, visibility 180ms ease;
     }

     .dialog-backdrop.open {
       opacity: 1;
       visibility: visible;
       pointer-events: auto;
     }

     .dialog {
       width: min(100%, 440px);
       background: var(--surface-solid);
       border-radius: 24px;
       padding: 28px;
       border: 1px solid rgba(19, 32, 51, 0.08);
       box-shadow: 0 24px 70px rgba(10, 16, 28, 0.28);
       transform: translateY(10px) scale(0.98);
       transition: transform 180ms ease;
     }

     .dialog-backdrop.open .dialog {
       transform: translateY(0) scale(1);
     }

     .dialog-icon {
       width: 52px;
       height: 52px;
       border-radius: 16px;
       display: grid;
       place-items: center;
       background: rgba(229, 72, 77, 0.1);
       color: var(--danger);
       font-size: 1.4rem;
       margin-bottom: 18px;
     }

     .dialog h2 {
       margin: 0 0 8px;
       font-size: 1.55rem;
       letter-spacing: -0.03em;
     }

     .dialog p {
       margin-bottom: 24px;
     }

     .dialog-actions {
       display: flex;
       justify-content: flex-end;
       gap: 12px;
       flex-wrap: wrap;
     }

     .status {
       min-height: 1.5em;
       color: #11845b;
       font-weight: 600;
       margin-top: 14px;
     }

